package dk.starswordmaster.progression;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class StatBonusesTest {
 private PlayerProgress stats(int strength,int agility,int endurance,int spirit){var p=new Properties();p.setProperty("xp","200000");int[] values={strength,agility,endurance,spirit};for(var s:PlayerProgress.Stat.values())p.setProperty("stat."+s,Integer.toString(values[s.ordinal()]));p.setProperty("mana","0");return PlayerProgress.fromProperties(p);}
 @Test public void zeroStatsPreserveOriginalRegeneration(){var p=stats(0,0,0,0);var b=p.bonuses();assertEquals(0,b.miningSpeed(),0);assertEquals(0,b.movementSpeed(),0);assertEquals(0,b.health(),0);assertEquals(0,b.manaRegeneration(),0);assertEquals(0.15,p.manaRegenPerTick(false),0);assertEquals(0.04,p.manaRegenPerTick(true),0);}
 @Test public void lowStatsGiveSmallPredictableBonuses(){var p=stats(1,1,1,1);var b=p.bonuses();assertEquals(0.01,b.miningSpeed(),1e-9);assertEquals(0.002,b.movementSpeed(),1e-9);assertEquals(0.1,b.health(),1e-9);assertEquals(0.01,b.manaRegeneration(),1e-9);assertEquals(0.025,b.abilityDamage(),1e-9);assertEquals(0.01,b.cooldownReduction(),1e-9);assertEquals(5,b.stamina());assertEquals(5,b.mana());}
 @Test public void miningCapsAtFiftyPercent(){assertEquals(0.49,stats(49,0,0,0).bonuses().miningSpeed(),1e-9);assertEquals(0.5,stats(50,0,0,0).bonuses().miningSpeed(),0);assertEquals(0.5,stats(495,0,0,0).bonuses().miningSpeed(),0);}
 @Test public void movementCapsAtTwentyPercent(){assertEquals(0.198,stats(0,99,0,0).bonuses().movementSpeed(),1e-9);assertEquals(0.2,stats(0,100,0,0).bonuses().movementSpeed(),0);assertEquals(0.2,stats(0,495,0,0).bonuses().movementSpeed(),0);assertEquals(0.4,stats(0,495,0,0).bonuses().cooldownReduction(),0);}
 @Test public void extraHealthCapsAtTenHealth(){assertEquals(9.9,stats(0,0,99,0).bonuses().health(),1e-9);assertEquals(10,stats(0,0,100,0).bonuses().health(),0);assertEquals(10,stats(0,0,495,0).bonuses().health(),0);assertEquals(2475,stats(0,0,495,0).bonuses().stamina());}
 @Test public void regenerationCapsAtDoubleAndCombatRemainsSlower(){var p=stats(0,0,0,495);assertEquals(1,p.bonuses().manaRegeneration(),0);assertEquals(0.3,p.manaRegenPerTick(false),1e-9);assertEquals(0.08,p.manaRegenPerTick(true),1e-9);assertEquals(0.99,stats(0,0,0,99).bonuses().manaRegeneration(),1e-9);for(int i=0;i<20;i++)p.tick(false);assertEquals(6,p.mana(),1e-8);}
 @Test public void regenerationCannotOverflowManaCapacity(){var p=stats(0,0,0,100);var props=p.toProperties();props.setProperty("mana",Double.toString(p.maxMana()-0.01));p=PlayerProgress.fromProperties(props);p.tick(false);assertEquals(p.maxMana(),p.mana(),0);}
 @Test public void existingRankAndPassiveBonusesStillCombineWithHighStats(){
  var props=stats(100,100,100,100).toProperties();for(Skill s:Skill.values())props.setProperty("practice."+s,"10000");var p=PlayerProgress.fromProperties(props);assertTrue(p.chooseClass(PlayerProgress.PlayerClass.MAGE));
  for(String id:new String[]{"spark","mana_control","arcane_mastery","fire_affinity","frost_touch","frost_affinity","mend","restorative_affinity","quick_cut","quick_dash","flow_training","heavy_cut","heavy_sweep","impact_training"})assertTrue(id,p.unlock(id));
  assertEquals(3,p.rank());assertEquals(3.65,p.damageMultiplier(),1e-9);p.setStyle(PlayerProgress.SwordStyle.HEAVY);assertEquals(3.65*1.15,p.damageMultiplier(Ability.ALL.get("quick_cut")),1e-9);assertEquals(10.8,p.manaCost(Ability.ALL.get("spark")),1e-9);assertEquals(29,p.cooldownTicks(Ability.ALL.get("frost_touch")));p.setStyle(PlayerProgress.SwordStyle.QUICK);assertEquals(22,p.cooldownTicks(Ability.ALL.get("quick_cut")));assertEquals(1.25,p.healingMultiplier(),0);assertEquals(838,p.maxMana(),0);assertEquals(699,p.maxStamina(),0);assertEquals(0.3,p.manaRegenPerTick(false),1e-9);
 }
 @Test public void oldSaveFieldsAndAllocatedPointsDoNotChangeWhenReadingBonuses(){var p=stats(40,40,40,40);var before=p.toProperties();for(int i=0;i<100;i++)p.bonuses();assertEquals(before,p.toProperties());var q=PlayerProgress.fromProperties(before);assertEquals(p.bonuses(),q.bonuses());assertEquals(before,q.toProperties());assertEquals(335,q.statPoints().intValueExact());assertEquals(99,q.points().intValueExact());assertEquals("1",q.toProperties().getProperty("schema"));}
}
